/* 話し言葉から目的地クエリを抽出。
   例: 「栃木県の男体山の駐車場まで連れて行ってください」→「栃木県の男体山の駐車場」
       「近くのコンビニに行きたいです」→「近くのコンビニ」
       「take me to Tokyo Station please」→「Tokyo Station」 */
function extractDestQuery(raw){
  let q = (raw||"");
  // 先頭のフィラー
  q = q.replace(/^\s*(えっと|ええと|あの|あのー|うーんと?|そうだ|じゃあ|では|やっぱり|やっぱ)\s*[、,]?\s*/ig,"");
  // 行き先変更の枕詞（日本語）
  q = q.replace(/(行き先を|行き先は|目的地を|目的地は|目的地に)/g,"");
  // 日本語: 助詞(まで/へ/に)＋移動動詞をまとめて除去
  q = q.replace(/(まで|へ|に)?\s*(連れて行って|連れてって|連れていって|行きたい|行って|行こう|向かって|向かいたい|案内して|案内お願いします|案内お願い|ナビして|案内)/g,"");
  // 日本語: 文末の丁寧表現・語尾
  q = q.replace(/(ください|下さい|お願いします|お願いね|お願い|ちょうだい|頂戴|です|でお願いします|して|ね|よ|な)+\s*$/g,"");
  // 日本語: 文末に残った助詞
  q = q.replace(/(まで|へ|に)\s*$/,"");
  // 英語: 前置の移動表現（語境界つきで "Tokyo" 等を誤爆させない）
  q = q.replace(/\b(please\s+)?(navigate to|take me to|drive to|walk to|head to|directions?\s+to|route to|go to|to)\b\s*/ig," ");
  q = q.replace(/\b(change|set)\s+destination\s+to\b\s*/ig," ");
  // 英語: 文末の丁寧語
  q = q.replace(/\b(please|thanks|thank you)\b\s*$/ig,"");
  // 記号・空白整理
  q = q.replace(/[、。,]/g," ").replace(/\s+/g," ").trim();
  return q;
}

