/* ============================ 目的地検索 ============================ */
// 目的地を確定してルートを引く（テキスト検索・地図クリック 共通）
function setDestinationCandidate(loc, name){
  S.destination = loc;
  S.destName = name || (S.lang==="ja"?"選択した地点":"selected point");
  S.waypoints = [];
  botSay(T().destSet(S.destName));
  buildRoute();
}

function searchDestination(query){
  if(!S.places){toast("Map not ready");return;}
  if(!query){ botSay(T().needDest); return; }
  botSay(T().searching(query), false);
  const req={ query, fields:["name","geometry","formatted_address"] };
  if(S.me) req.locationBias=new google.maps.Circle({center:S.me,radius:30000});
  S.places.findPlaceFromQuery(req,(res,status)=>{
    if(status===google.maps.places.PlacesServiceStatus.OK && res && res[0] && res[0].geometry){
      const p=res[0];
      setDestinationCandidate(p.geometry.location, p.name||query);
    }else{
      // フォールバック: geocoder
      S.geocoder.geocode({address:query},(gr,gs)=>{
        if(gs==="OK"&&gr[0]){
          setDestinationCandidate(gr[0].geometry.location, gr[0].formatted_address);
        }else{ botSay(T().notFound(query)); }
      });
    }
  });
}

/* 地図クリック：POIを目的地候補にする */
function pickPlaceAsDestination(placeId, latLng){
  if(!S.places){ if(latLng) pickLatLngAsDestination(latLng); return; }
  S.places.getDetails({placeId, fields:["name","geometry","formatted_address"]}, (p,status)=>{
    if(status===google.maps.places.PlacesServiceStatus.OK && p && p.geometry){
      setDestinationCandidate(p.geometry.location, p.name||p.formatted_address);
    }else if(latLng){
      pickLatLngAsDestination(latLng);
    }
  });
}

/* 地図クリック：施設でない地点は逆ジオコードして目的地候補にする */
function pickLatLngAsDestination(latLng){
  if(!S.geocoder){ setDestinationCandidate(latLng, null); return; }
  S.geocoder.geocode({location:latLng},(gr,gs)=>{
    const name=(gs==="OK"&&gr&&gr[0]) ? gr[0].formatted_address
      : `${latLng.lat().toFixed(5)}, ${latLng.lng().toFixed(5)}`;
    setDestinationCandidate(latLng, name);
  });
}

