/* ============================ 音声合成 (TTS) ============================ */
let voices=[];
// 機械的・ノベルティ音声（除外したい）
const BAD_VOICE = /(albert|bad news|bahh|bells|boing|bubbles|cellos|deranged|good news|jester|organ|pipe organ|superstar|trinoids|whisper|wobble|zarvox|eloquence|espeak|compact|maged|fred|junior|kathy|ralph|hysterical)/i;
// 自然・高品質音声（優先したい）
const GOOD_VOICE = {
  ja: /(google|siri|kyoko|o-?ren|otoya|hattori|sayaka|nanami|ayumi|natural|neural|premium|enhanced)/i,
  en: /(google|siri|samantha|ava|allison|aria|jenny|guy|natural|neural|premium|enhanced|karen|serena|moira|tessa|nicky|joana|zoe|evan)/i
};
function loadVoices(){ voices=window.speechSynthesis?speechSynthesis.getVoices():[]; }
if(window.speechSynthesis){
  loadVoices();
  speechSynthesis.onvoiceschanged=()=>{ loadVoices(); if(typeof populateVoiceSelect==="function") populateVoiceSelect(); };
}

// 音声を品質スコアリングして一番自然なものを選ぶ
function scoreVoice(v, langKey){
  if(!v || !v.lang) return -1e9;
  const lp=v.lang.toLowerCase();
  if(!lp.startsWith(langKey==="ja"?"ja":"en")) return -1e9;
  const name=v.name||"";
  let s=0;
  if(BAD_VOICE.test(name)) s-=200;
  if(GOOD_VOICE[langKey].test(name)) s+=60;
  if(/google/i.test(name)) s+=45;                       // ChromeのGoogleニューラル音声が最も自然
  if(/(siri|natural|neural|premium|enhanced)/i.test(name)) s+=35;
  if(v.localService===false) s+=15;                     // ネットワーク音声は概して高品質
  if(langKey==="en" && /en[-_]us/i.test(lp)) s+=8;
  if(langKey==="ja" && /ja[-_]jp/i.test(lp)) s+=8;
  if(v.default) s+=3;
  return s;
}
function bestVoice(langKey){
  let best=null, bestS=-1e9;
  for(const v of voices){ const sc=scoreVoice(v,langKey); if(sc>bestS){bestS=sc; best=v;} }
  return best;
}
function pickVoice(langKey){
  const saved=localStorage.getItem("nav_voice_"+langKey);
  if(saved){ const hit=voices.find(v=>v.voiceURI===saved||v.name===saved); if(hit) return hit; }
  return bestVoice(langKey);
}
function tts(text){
  if(!S.tts || !window.speechSynthesis) return;
  try{
    const u=new SpeechSynthesisUtterance(text);
    const langKey=S.lang==="ja"?"ja":"en";
    u.lang = langKey==="ja" ? "ja-JP" : "en-US";
    const v=pickVoice(langKey);
    if(v){ u.voice=v; u.lang=v.lang; }
    // やわらかく落ち着いた読み上げ（速すぎ・平坦すぎを避ける）
    u.rate=0.98; u.pitch=1.02; u.volume=1;
    speechSynthesis.cancel(); speechSynthesis.speak(u);
  }catch(e){}
}

