function populateVoiceSelect(){
  const sel=$("voiceSelect"); if(!sel) return;
  const langKey=S.lang==="ja"?"ja":"en";
  const saved=localStorage.getItem("nav_voice_"+langKey)||"";
  const list=voices.filter(v=>v.lang && v.lang.toLowerCase().startsWith(langKey==="ja"?"ja":"en"))
