/* ============================ 音声認識 (STT / ハンズフリー) ============================ */
const SR = window.SpeechRecognition||window.webkitSpeechRecognition;
let recog=null;
let listening=false;    // 実際に認識中か
let wantListen=false;   // ハンズフリーを継続したいか（ユーザー意図）
let speaking=false;     // TTS発話中か（自分の声を拾わないため）
let ignoreUntil=0;      // 発話直後のエコー無視の締切(ms)
let restartTimer=null;

function buildRecog(){
  if(!SR) return null;
  const r=new SR();
  r.lang = S.lang==="ja" ? "ja-JP" : "en-US";
  r.interimResults=false; r.maxAlternatives=1;
  r.continuous=true;    // ← 連続認識（ボタンを押し続けなくてよい）
  r.onstart=()=>{ listening=true; updateMicUI(); };
  r.onend=()=>{
    listening=false; updateMicUI();
    // ブラウザは無音/一定時間で勝手に停止するので、意図が続く限り自動再開
    if(wantListen) scheduleRestart(300);
  };
  r.onerror=e=>{
    if(e.error==="not-allowed"||e.error==="service-not-allowed"){
      wantListen=false; localStorage.setItem("nav_handsfree","0");
      updateMicUI(); toast(T().micDenied); return;
    }
    // no-speech / aborted / network 等は onend の自動再開に任せる
  };
  r.onresult=e=>{
    const res=e.results[e.results.length-1];
    if(!res || !res.isFinal) return;
    // 自分のTTSやその残響を拾わない
    if(speaking || Date.now()<ignoreUntil) return;
    const t=(res[0]&&res[0].transcript||"").trim();
    if(t) handleInput(t);
  };
  return r;
}

function scheduleRestart(delay){
  clearTimeout(restartTimer);
  restartTimer=setTimeout(()=>{
    if(wantListen && !listening){ try{ recog && recog.start(); }catch(e){} }
  }, delay||300);
}

function startHandsFree(){
  if(!SR){ toast("Speech recognition not supported"); return; }
  wantListen=true; localStorage.setItem("nav_handsfree","1");
  if(!recog) recog=buildRecog();
  updateMicUI();
  try{ recog.start(); }catch(e){ /* already running */ }
  botSay(T().listenOn, false);
