// 住所文字列から「都道府県＋市区町村」を抽出（TTS/表示用に短く）
function shortArea(addr){
  if(!addr) return "";
  const a=String(addr).replace(/^日本[、,]?\s*/,"").replace(/〒?\d{3}-?\d{4}\s*/,"");
  const m=a.match(/([^\s、,]+?[都道府県])?\s*([^\s、,0-9０-９]+?[市区町村])/);
  if(m && (m[1]||m[2])) return (m[1]||"")+(m[2]||"");
  return a.split(/[、,]/)[0].slice(0,24);
}
function candLabel(c){ return c.area ? `${c.name}（${c.area}）` : c.name; }

// テキスト/音声クエリ → 候補を出して確認（即ルートは引かない）
function searchDestination(query, opts){
  if(!S.places){toast("Map not ready");return;}
  if(!query){ botSay(T().needDest); return; }
  const confirm = !(opts && opts.confirm===false);
  botSay(T().searching(query), false);
  const req={ query };
  if(S.me){ req.location=S.me; req.radius=30000; }
  S.places.textSearch(req,(res,status)=>{
    if(status===google.maps.places.PlacesServiceStatus.OK && res && res.length){
      const cands=res.slice(0,MAX_CANDIDATES)
        .filter(p=>p.geometry && p.geometry.location)
        .map(p=>({loc:p.geometry.location, name:p.name||query, area:shortArea(p.formatted_address)}));
      if(!cands.length){ botSay(T().notFound(query)); return; }
      if(confirm) presentCandidates(cands);
      else setDestinationCandidate(cands[0].loc, candLabel(cands[0]));
    }else{
      // フォールバック: geocoder（単一候補）
      S.geocoder.geocode({address:query},(gr,gs)=>{
        if(gs==="OK"&&gr[0]){
          const c={loc:gr[0].geometry.location, name:gr[0].formatted_address, area:shortArea(gr[0].formatted_address)};
          if(confirm) presentCandidates([c]);
          else setDestinationCandidate(c.loc, candLabel(c));
        }else{ botSay(T().notFound(query)); }
      });
    }
  });
}

/* ============================ 目的地の確認ステップ ============================ */
function styleCandMarker(mk,i,active){
  mk.setIcon({path:google.maps.SymbolPath.CIRCLE, scale:active?15:11,
    fillColor:active?"#2ee6a6":"#ffb020", fillOpacity:active?1:.85,
    strokeColor:"#04231a", strokeWeight:2});
  mk.setLabel({text:String(i+1), color:"#04231a", fontWeight:"700", fontSize:"12px"});
  mk.setZIndex(active?1000:500);
}
function fitToCandidates(cands){
  if(cands.length<=1){ S.map.panTo(cands[0].loc); if(!S.navOn) S.map.setZoom(15); return; }
  const b=new google.maps.LatLngBounds();
  cands.forEach(c=>b.extend(c.loc));
  if(S.me) b.extend(S.me);
  S.map.fitBounds(b,80);
}
function presentCandidates(cands){
  clearPending();  // 前の確認を破棄
  const markers=cands.map((c,i)=>{
    const mk=new google.maps.Marker({map:S.map, position:c.loc});
    styleCandMarker(mk,i,i===0);
    return mk;
  });
  S.pending={cands, idx:0, markers, timer:null};
  fitToCandidates(cands);
  offerCandidate();
}
function offerCandidate(){
  const p=S.pending; if(!p) return;
  const c=p.cands[p.idx];
  p.markers.forEach((mk,i)=>styleCandMarker(mk,i,i===p.idx));
  S.map.panTo(c.loc);
  const more = p.cands.length>1 ? " "+T().candCount(p.idx+1,p.cands.length) : "";
  botSay(T().confirmDest(candLabel(c))+more);
  startPendingTimeout();
}
function startPendingTimeout(){
  const p=S.pending; if(!p) return;
  clearTimeout(p.timer);
  p.timer=setTimeout(()=>{ botSay(T().confirmTimeout); clearPending(); }, CONFIRM_TIMEOUT_MS);
}
function confirmCandidate(){
  const p=S.pending; if(!p) return;
  const c=p.cands[p.idx];
  clearPending();
  setDestinationCandidate(c.loc, candLabel(c));
}
function nextCandidate(){
  const p=S.pending; if(!p) return;
  if(p.idx < p.cands.length-1){ clearTimeout(p.timer); p.idx++; offerCandidate(); }
  else { botSay(T().noMoreCand); clearPending(); }
}
function clearPending(){
  const p=S.pending; if(!p) return;
  clearTimeout(p.timer);
  p.markers.forEach(mk=>mk.setMap(null));
  S.pending=null;
}
// 確認待ち中の応答を yes / no / cancel / other に分類
function classifyConfirm(t){
  if(/(やめ|キャンセル|中止|なし|stop|cancel)/i.test(t)) return "cancel";
  if(/(違う|ちがう|いいえ|いや|ちゃう|じゃない|別の?|ほか|他|次|つぎ|もう一[度回]|やり直|no|nope|not)/i.test(t)) return "no";
  if(/(はい|うん|ええ|そう|それで?|ok|okay|オッケー?|おっけー?|了解|りょ|お願い|おねがい|決定|確定|いい[よね]?|正解|yes|yep|yeah|right|correct|sure)/i.test(t)) return "yes";
  return "other";
}

